// msg.payload = change record from abraflexi-webhook
const data = msg.payload;
const metrics = data.metrics || {};
const cycles  = metrics.cycles || 0;
const SPIKE   = 1.0;

// Aggregate pass_N_op_dir raw values
const agg = {};
for (const [key, rawVal] of Object.entries(metrics)) {
    if (key === 'cycles' || key === 'delay') continue;
    const m = key.match(/^pass_\d+_(.+)_(read|write)$/);
    if (!m) continue;
    const v = parseFloat(rawVal);
    if (isNaN(v)) continue;
    const k = `${m[1]}:${m[2]}`;
    if (!agg[k]) agg[k] = {op: m[1], dir: m[2], vals: []};
    agg[k].vals.push(v);
}

const rows = Object.values(agg)
    .map(({op, dir, vals}) => ({
        op, dir,
        avg:    vals.reduce((s, v) => s + v, 0) / vals.length,
        max:    Math.max(...vals),
        spikes: vals.filter(v => v >= SPIKE).length
    }))
    .sort((a, b) => a.op.localeCompare(b.op) || a.dir.localeCompare(b.dir));

const SEP = '+' + [16,7,8,8,11].map(n => '-'.repeat(n)).join('+') + '+';
let table = `AbraFlexi Benchmark — ${cycles} cycles, delay ${metrics.delay||0}s\n`;
table += `Status: ${(data.status||'?').toUpperCase()}  |  ${data['@timestamp']||data.timestamp||""}\n\n`;
table += SEP + '\n';
table += '| Operation      | Dir   | Avg    | Max    | 1s spikes |\n';
table += SEP + '\n';
for (const r of rows) {
    table += `| ${r.op.replace(/_/g,' ').padEnd(14)} | ${r.dir.padEnd(5)} | `
           + `${(r.avg.toFixed(3)+'s').padEnd(6)} | ${(r.max.toFixed(3)+'s').padEnd(6)} | `
           + `${String(r.spikes).padEnd(9)} |\n`
           + SEP + '\n';
}

const ts = data['@timestamp'] || data.timestamp || '';
node.status({
    fill:  data.status === 'success' ? 'green' : (data.status === 'error' ? 'red' : 'yellow'),
    shape: 'dot',
    text:  `${cycles} cycles @ ${new Date(ts).toLocaleTimeString('cs-CZ',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}`
});

const baseUrl = env.get('ABRAFLEXI_URL');
const company = env.get('ABRAFLEXI_COMPANY');
const auth    = 'Basic ' + Buffer.from(env.get('ABRAFLEXI_LOGIN') + ':' + env.get('ABRAFLEXI_PASSWORD')).toString('base64');
const hdrs    = {Authorization: auth, Accept: 'application/json'};

function mkReq(evidence, qs, topic) {
    return {payload: null, method: 'GET', topic,
            url: `${baseUrl}/c/${company}/${evidence}.json?${qs}`,
            headers: hdrs};
}

return [
    {...msg, payload: table},
    mkReq('faktura-vydana', 'order=id%40D&limit=5&detail=full',   'invoice'),
    mkReq('banka',          'order=id%40D&limit=5',               'bank_move'),
    mkReq('adresar',        'order=id%40D&limit=5',               'address')
];

const records = (msg.payload.winstrom || {})['faktura-vydana'] || [];
if (!records.length) { msg.payload = 'No invoices found in AbraFlexi.'; return msg; }

const D = '-'.repeat(64);
let out = `Last ${records.length} invoice(s) from AbraFlexi:\n${D}\n`;
for (const inv of records) {
    out += `Code  : ${inv.kod||'?'}  |  Date: ${inv.datVyst||'?'}  |  Total: ${inv.sumCelkem||0} ${inv.mena||""}\n`;
    out += `Desc  : ${inv.popis||""}\n`;
    const items = Array.isArray(inv.polozkyDokladu) ? inv.polozkyDokladu
                : (inv.polozkyDokladu ? [inv.polozkyDokladu] : []);
    if (items.length) {
        for (const i of items) {
            out += `  Item: ${i.nazev||i.Nazev||'?'}  × ${i.mnozMj||1}  @  ${i.cenaMj||0} ${i.mena||""}\n`;
        }
        out += `  ──── Total: ${inv.sumCelkem||0} ${inv.mena||""}\n`;
    } else {
        out += `  Items: (none — created with bezPolozek=true)\n`;
    }
    out += `${D}\n`;
}
msg.payload = out;
return msg;

const records = (msg.payload.winstrom || {})['banka'] || [];
if (!records.length) { msg.payload = 'No bank moves found in AbraFlexi.'; return msg; }

const D = '-'.repeat(64);
let out = `Last ${records.length} bank move(s) from AbraFlexi:\n${D}\n`;
for (const bm of records) {
    const amount = bm.sumCelkem !== undefined ? `${bm.sumCelkem} ${bm.mena||""}` : 'N/A';
    out += `Code   : ${bm.kod||'?'}  |  Date: ${bm.datVyst||'?'}\n`;
    out += `Amount : ${amount}\n`;
    out += `VarSym : ${bm.varSym||'?'}  |  Desc: ${bm.popis||""}\n`;
    out += `${D}\n`;
}
msg.payload = out;
return msg;

const records = (msg.payload.winstrom || {})['adresar'] || [];
if (!records.length) { msg.payload = 'No addresses found in AbraFlexi.'; return msg; }

const D = '-'.repeat(64);
let out = `Last ${records.length} address(es) from AbraFlexi:\n${D}\n`;
for (const a of records) {
    out += `Name    : ${a.nazev||'?'}\n`;
    out += `Email   : ${a.email||'?'}  |  Phone: ${a.tel||'?'}\n`;
    out += `City    : ${a.mesto||'?'}  |  Country: ${a.stat||'?'}\n`;
    out += `${D}\n`;
}
msg.payload = out;
return msg;
